rm(list = ls())

mydir <- this.path::here()
setwd(mydir)


source("elppd_utils.R")

# User inputs

sigma2 <- 1
tau2 <- 1e2

# Load simulated data and exact ELPPD (generated by Gaussian_simulation.R)
load("Gaussian_data.RData")
n <- nrow(X)
d <- ncol(X)


# Fold settings

K.vec <- c(5, 10, 20, 50, 100)
S = 1e4

# Colors

submethod.cols <- c("steelblue",   # IS
                    "darkorange",  # TIS
                    "forestgreen"  # PSIS
                    )

box.cols <- rep(submethod.cols, 3)


# Adaptive approach for par(mfrow)
num_plots <- length(K.vec)
rows <- floor(sqrt(num_plots))
cols <- ceiling(num_plots / rows)

# Adaptive width and height
pdf_width <- 5 * cols
pdf_height <- 4.5 * rows


# 1. ELPPD comparison plot


plot_elpd_panel <- function(results,
                            true_elpd,
                            title,
                            ylim = NULL){
  
  plot.data <- list(
    results$elppd_g_is,
    results$elppd_g_tis,
    results$elppd_g_psis,
    
    results$elppd_b_is,
    results$elppd_b_tis,
    results$elppd_b_psis,
    
    results$elppd_z_is,
    results$elppd_z_tis,
    results$elppd_z_psis
  )
  
  boxplot(plot.data,
          col = box.cols,
          border = "black",
          las = 2,
          outline = FALSE,
          xaxt = "n",
          ylim = ylim,
          ylab = "ELPPD",
          main = title)
  
  axis(1,
       at = 1:9,
       labels = rep(c("IS", "TIS", "PSIS"), 3),
       las = 2)
  
  axis(1,
       at = c(2, 5, 8),
       labels = c("Gelfand", "Bronze", "Zanella"),
       tick = FALSE,
       line = 3)
  
  abline(h = true_elpd,
         col = "red",
         lwd = 2,
         lty = 2)
  
  legend("bottomright",
         legend = c("IS", "TIS", "PSIS", "Gold ELPPD"),
         fill = c(submethod.cols, NA),
         border = c("black", "black", "black", NA),
         lty = c(NA, NA, NA, 2),
         lwd = c(NA, NA, NA, 2),
         col = c(NA, NA, NA, "red"),
         bty = "n",
         cex = 0.9)
}


# Helper function to extract ELPPD values

extract_elppd <- function(results){
  
  c(results$elppd_g_is,
    results$elppd_g_tis,
    results$elppd_g_psis,
    
    results$elppd_b_is,
    results$elppd_b_tis,
    results$elppd_b_psis,
    
    results$elppd_z_is,
    results$elppd_z_tis,
    results$elppd_z_psis)
}


# ---------------------------------------------------------
# First pass: compute common y-axis limits
# ---------------------------------------------------------

all.elppd <- c()

for(K in K.vec){
  
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  
  all.elppd <- c(all.elppd,
                 extract_elppd(results),
                 exact_elppd)
}

common.ylim <- range(all.elppd, na.rm = TRUE)


# ---------------------------------------------------------
# ELPD comparison plot
# ---------------------------------------------------------

pdf("Gaussian_k_fold_elpd_comparison.pdf",
    width = pdf_width,
    height = pdf_height)

par(mfrow = c(rows, cols),
    mar = c(6,4,3,1),
    mgp = c(2,0.7,0),
    tcl = -0.3)

for(K in K.vec){
  
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  
  plot_elpd_panel(results = results,
                  true_elpd = exact_elppd,
                  title = paste0("K = ", K),
                  ylim = common.ylim)
}

dev.off()



# 2. Standard Errors comparison plot


plot_var_panel_estimator <- function(results,
                                     title,
                                     ylim = NULL){
  
  plot.data <- list(
    results$var_g_is,
    results$var_g_tis,
    results$var_g_psis,
    
    results$var_b_is,
    results$var_b_tis,
    results$var_b_psis,
    
    results$var_z_is,
    results$var_z_tis,
    results$var_z_psis
  )
  
  # Sample variances of the estimators
  samp.var <- c(
    var(results$elppd_g_is),
    var(results$elppd_g_tis),
    var(results$elppd_g_psis),
    
    var(results$elppd_b_is),
    var(results$elppd_b_tis),
    var(results$elppd_b_psis),
    
    var(results$elppd_z_is),
    var(results$elppd_z_tis),
    var(results$elppd_z_psis)
  )
  
  pos <- 1:9
  
  boxplot(plot.data,
          col = box.cols,
          border = "black",
          las = 2,
          outline = FALSE,
          xaxt = "n",
          ylim = ylim,
          log = "y",
          ylab = "Estimator Variance (log-scale)",
          main = title)
  
  axis(1,
       at = 1:9,
       labels = rep(c("IS", "TIS", "PSIS"), 3),
       las = 2)
  
  axis(1,
       at = c(2, 5, 8),
       labels = c("Gelfand", "Bronze", "Zanella"),
       tick = FALSE,
       line = 3)
  
  # Sample variance benchmark
  segments(pos - 0.25,
           samp.var,
           pos + 0.25,
           samp.var,
           lwd = 2,
           col = "red")
  
  legend("topright",
         legend = c("IS est.var",
                    "TIS est.var",
                    "PSIS est.var",
                    "Sample var"),
         fill = c(box.cols[c(1,2,3)], NA),
         border = c("black", "black", "black", NA),
         lty = c(NA, NA, NA, 1),
         lwd = c(NA, NA, NA, 2),
         col = c(NA, NA, NA, "red"),
         bty = "n",
         cex = 0.9)
}



plot_se_panel <- function(results,
                          title,
                          ylim = NULL){
  
  plot.data <- list(
    sqrt(results$var_g_is),
    sqrt(results$var_g_tis),
    sqrt(results$var_g_psis),
    
    sqrt(results$var_b_is),
    sqrt(results$var_b_tis),
    sqrt(results$var_b_psis),
    
    sqrt(results$var_z_is),
    sqrt(results$var_z_tis),
    sqrt(results$var_z_psis)
  )
  
  # Sample standard deviations of the estimators
  samp.se <- c(
    sd(results$elppd_g_is),
    sd(results$elppd_g_tis),
    sd(results$elppd_g_psis),
    
    sd(results$elppd_b_is),
    sd(results$elppd_b_tis),
    sd(results$elppd_b_psis),
    
    sd(results$elppd_z_is),
    sd(results$elppd_z_tis),
    sd(results$elppd_z_psis)
  )
  
  pos <- 1:9
  
  boxplot(plot.data,
          col = box.cols,
          border = "black",
          las = 2,
          outline = FALSE,
          xaxt = "n",
          ylim = ylim,
          log = "y",
          ylab = "Standard Error (log-scale)",
          xlab = "Method",
          main = title)
  
  axis(1,
       at = 1:9,
       labels = rep(c("IS", "TIS", "PSIS"), 3),
       las = 2)
  
  axis(1,
       at = c(2, 5, 8),
       labels = c("Gelfand", "Bronze", "Zanella"),
       tick = FALSE,
       line = 3)
  
  # Sample standard deviation benchmark
  segments(pos - 0.25,
           samp.se,
           pos + 0.25,
           samp.se,
           lwd = 2,
           col = "red")
  
  legend("topright",
         legend = c("IS est.se",
                    "TIS est.se",
                    "PSIS est.se",
                    "Sample SD"),
         fill = c(submethod.cols, NA),
         border = c("black", "black", "black", NA),
         lty = c(NA, NA, NA, 1),
         lwd = c(NA, NA, NA, 2),
         col = c(NA, NA, NA, "red"),
         bty = "n",
         cex = 0.9)
}

extract_se_estimator <- function(results){
  
  c(sqrt(results$var_g_is),
    sqrt(results$var_g_tis),
    sqrt(results$var_g_psis),
    
    sqrt(results$var_b_is),
    sqrt(results$var_b_tis),
    sqrt(results$var_b_psis),
    
    sqrt(results$var_z_is),
    sqrt(results$var_z_tis),
    sqrt(results$var_z_psis),
    
    # include sample standard deviations
    sd(results$elppd_g_is),
    sd(results$elppd_g_tis),
    sd(results$elppd_g_psis),
    
    sd(results$elppd_b_is),
    sd(results$elppd_b_tis),
    sd(results$elppd_b_psis),
    
    sd(results$elppd_z_is),
    sd(results$elppd_z_tis),
    sd(results$elppd_z_psis))
}

all.se.estimator <- c()
for(K in K.vec){
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  all.se.estimator <- c(all.se.estimator, extract_se_estimator(results))
}

min_val_se <- min(all.se.estimator[all.se.estimator > 0], na.rm = TRUE)
max_val_se <- max(all.se.estimator, na.rm = TRUE)
common.se.ylim <- c(min_val_se, max_val_se)

pdf("se.pdf", width = pdf_width, height = pdf_height)
par(mfrow = c(rows, cols),
    mar = c(6, 4, 3, 1),
    mgp = c(2, 0.7, 0),
    tcl = -0.3)

for(K in K.vec){
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  plot_se_panel(results = results,
                title = paste0("K = ", K),
                ylim = common.se.ylim)
}
dev.off()


# 3. Asymptotic Variance comparison plot


plot_var_panel_asymp <- function(results,
                                 title,
                                 S_mcmc = S,
                                 ylim = NULL){
  
  # Scale estimated variances by S_mcmc to put them on the asymptotic scale (sigma2_ELPPD)
  plot.data <- list(
    S_mcmc * results$var_g_is,
    S_mcmc * results$var_g_tis,
    S_mcmc * results$var_g_psis,
    
    S_mcmc * results$var_b_is,
    S_mcmc * results$var_b_tis,
    S_mcmc * results$var_b_psis,
    
    S_mcmc * results$var_z_is,
    S_mcmc * results$var_z_tis,
    S_mcmc * results$var_z_psis
  )
  
  # Sample variances on asymptotic scale
  samp.var <- S_mcmc * c(
    var(results$elppd_g_is),
    var(results$elppd_g_tis),
    var(results$elppd_g_psis),
    
    var(results$elppd_b_is),
    var(results$elppd_b_tis),
    var(results$elppd_b_psis),
    
    var(results$elppd_z_is),
    var(results$elppd_z_tis),
    var(results$elppd_z_psis)
  )
  
  pos <- 1:9
  
  boxplot(plot.data,
          col = box.cols,
          border = "black",
          las = 2,
          outline = FALSE,
          xaxt = "n",
          ylim = ylim,
          log = "y",
          ylab = expression(S %*% Variance ~ (log - scale)),
          main = title)
  
  axis(1,
       at = 1:9,
       labels = rep(c("IS", "TIS", "PSIS"), 3),
       las = 2)
  
  axis(1,
       at = c(2, 5, 8),
       labels = c("Gelfand",
                  "Bronze",
                  "Zanella"),
       tick = FALSE,
       line = 3)
  
  # Sample variance benchmark
  segments(pos - 0.25,
           samp.var,
           pos + 0.25,
           samp.var,
           lwd = 2,
           col = "red")
  
  legend("topright",
         legend = c("IS asymp.var",
                    "TIS asymp.var",
                    "PSIS asymp.var",
                    "Sample var * S"),
         fill = c(box.cols[c(1,2,3)], NA),
         border = c("black",
                    "black",
                    "black",
                    NA),
         lty = c(NA,
                 NA,
                 NA,
                 1),
         lwd = c(NA,
                 NA,
                 NA,
                 2),
         col = c(NA,
                 NA,
                 NA,
                 "red"),
         bty = "n",
         cex = 0.9)
}


# ---------------------------------------------------------
# Helper function to extract variance values (Estimator Scale)
# ---------------------------------------------------------

extract_var_estimator <- function(results){
  
  c(results$var_g_is,
    results$var_g_tis,
    results$var_g_psis,
    
    results$var_b_is,
    results$var_b_tis,
    results$var_b_psis,
    
    results$var_z_is,
    results$var_z_tis,
    results$var_z_psis,
    
    # include sample variances
    var(results$elppd_g_is),
    var(results$elppd_g_tis),
    var(results$elppd_g_psis),
    
    var(results$elppd_b_is),
    var(results$elppd_b_tis),
    var(results$elppd_b_psis),
    
    var(results$elppd_z_is),
    var(results$elppd_z_tis),
    var(results$elppd_z_psis))
}


# ---------------------------------------------------------
# First pass: compute common y-axis limits
# ---------------------------------------------------------

all.var.estimator <- c()
all.var.asymp <- c()
S_mcmc <- S

for(K in K.vec){
  
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  
  vars_est <- extract_var_estimator(results)
  all.var.estimator <- c(all.var.estimator, vars_est)
  all.var.asymp <- c(all.var.asymp, S_mcmc * vars_est)
}

min_val_est <- min(all.var.estimator[all.var.estimator > 0], na.rm = TRUE)
max_val_est <- max(all.var.estimator, na.rm = TRUE)
common.var.estimator.ylim <- c(min_val_est, max_val_est)

min_val_asymp <- min(all.var.asymp[all.var.asymp > 0], na.rm = TRUE)
max_val_asymp <- max(all.var.asymp, na.rm = TRUE)
common.var.asymp.ylim <- c(min_val_asymp, max_val_asymp)


# ---------------------------------------------------------
# 1. Estimator Variance comparison plot
# ---------------------------------------------------------

pdf("Gaussian_k_fold_variance_estimator_comparison.pdf",
    width = pdf_width,
    height = pdf_height)

par(mfrow = c(rows, cols),
    mar = c(6,4,3,1),
    mgp = c(2,0.7,0),
    tcl = -0.3)

for(K in K.vec){
  
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  
  plot_var_panel_estimator(results = results,
                           title = paste0("K = ", K),
                           ylim = common.var.estimator.ylim)
}

dev.off()


# ---------------------------------------------------------
# 2. Asymptotic Variance comparison plot
# ---------------------------------------------------------

pdf("Gaussian_k_fold_variance_comparison.pdf",
    width = pdf_width,
    height = pdf_height)

par(mfrow = c(rows, cols),
    mar = c(6,4,3,1),
    mgp = c(2,0.7,0),
    tcl = -0.3)

for(K in K.vec){
  
  load(paste0(K, "_fold_elppd_Gaussian.RData"))
  
  plot_var_panel_asymp(results = results,
                       title = paste0("K = ", K),
                       S_mcmc = S_mcmc,
                       ylim = common.var.asymp.ylim)
}

dev.off()